#!/bin/bash\nset -e\n\necho \"🚀 Setting up AI Agent Organization Codespace...\"\n\n# Update system packages\nsudo apt-get update\nsudo apt-get install -y curl wget git jq postgresql-client redis-tools\n\n# Install Docker Compose\nsudo curl -L \"https://github.com/docker/compose/releases/latest/download/docker-compose-$(uname -s)-$(uname -m)\" -o /usr/local/bin/docker-compose\nsudo chmod +x /usr/local/bin/docker-compose\n\n# Install Python dependencies\necho \"📦 Installing Python dependencies...\"\npip install --upgrade pip setuptools wheel\n\n# Install backend requirements\nif [ -f \"backend/requirements.txt\" ]; then\n  pip install -r backend/requirements.txt\nfi\n\n# Install API requirements\nif [ -f \"api/requirements.txt\" ]; then\n  pip install -r api/requirements.txt\nfi\n\n# Install MCP server requirements\nif [ -f \"mcp-server/requirements.txt\" ]; then\n  pip install -r mcp-server/requirements.txt\nfi\n\n# Install Node dependencies for frontend\necho \"📦 Installing Node dependencies...\"\ncd frontend\nnpm install\ncd ..\n\n# Create nginx directory\nmkdir -p nginx\n\necho \"✅ Codespace setup complete!\"\necho \"\"\necho \"Next steps:\"\necho \"1. Run: docker compose up --build\"\necho \"2. Open http://localhost:5173 for the dashboard\"\necho \"3. API available at http://localhost:8000\"\necho \"\"\n"